import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <View nativeID="tile" style={styles.tile}>
        <Text style={styles.label}>1:1</Text>
      </View>
      {/* энд бичнэ үү: tile-г квадрат харьцаатай болго */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24 },
  tile: { width: "100%", backgroundColor: "#a5b4fc", borderRadius: 16, alignItems: "center", justifyContent: "center" },
  label: { color: "#312e81", fontSize: 20, fontWeight: "bold" },
});

registerRootComponent(App);

